import{d as c,C as t,o as g,c as u,j as a,a as s,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十四章","description":"以名、身、货的三问，理解知足知止与过度执藏的代价。","frontmatter":{"title":"道德经第四十四章","description":"以名、身、货的三问，理解知足知止与过度执藏的代价。","category":"guide","aliases":["道德经第四十四章","老子第四十四章","dao de jing chapter 44"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-44.md","filePath":"daoism/dao-de-jing/chapter-44.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-44.md"},y=c({...b,setup(p){const n=[{id:"three-questions",label:"名与身孰亲",showLabel:!0,sentences:[[{text:"名",glossary:"ming"},"与身",{text:"孰",glossary:"shu"},"亲？身与",{text:"货",glossary:"huo"},{text:"孰",glossary:"shu"},{text:"多",glossary:"duo"},"？得与",{text:"亡",glossary:"wang"},{text:"孰",glossary:"shu"},{text:"病",glossary:"bing"},"？"]],note:["【白话】声名与自身，哪一个更切近、更值得珍爱？自身与财货，哪一个更重要？获得外物与丧失自身，哪一个更是祸患？","【王弼注择要】「得多利而亡其身，何者为病也？」王弼将第三问明确落在得利与亡身的轻重，不仅比较普通的盈利与亏损。","【读法】名取声名义，与命名、名称分开。多在孰多中问看重，病作祸害、弊病；前两问为第三问铺垫，提醒得物未必就是自身受益。"]},{id:"cost-of-clinging",label:"甚爱必大费",showLabel:!0,sentences:[[{text:"甚爱",glossary:"shenai"},"必大费，"]],note:["【白话】过分执爱、不肯放开的，必然会付出很大的耗费。此处承接名货与自身的比较，反省的是无度的执取。","【读法】王弼以甚爱不与物通解释过度封闭的执爱，本页作转述。它不等于一切爱惜都会带来坏结果，也不否定实际照料与珍惜。"]},{id:"cost-of-hoarding",label:"多藏必厚亡",showLabel:!0,sentences:[[{text:"多",glossary:"duo"},{text:"藏",glossary:"cang"},"必厚",{text:"亡",glossary:"wang"},"。"]],note:["【白话】过度积藏、只想占有，便会招致重大的损失。厚亡不是多储存一点便必遭灾，而是对无度执藏及其后果的警戒。","【王弼注择要】「求之者多，攻之者众。」注从执藏不散引来争求、攻击解释「大费厚亡」，把代价放回人与物的关系。","【读法】藏读 cáng；厚为重、大。本章不据此禁止合理储备，也不能用它推断遭到侵害的人必因贪藏而受害。"]},{id:"enough-and-limits",label:"知足不辱，知止不殆",showLabel:!0,sentences:[["故",{text:"知足",glossary:"zhizu"},"不辱，",{text:"知止",glossary:"zhizhi"},"不",{text:"殆",glossary:"dai"},"，可以长久。"]],note:["【白话】所以，知道满足，便不因无尽逐求而自取困辱；知道停止的限度，便不因越界贪取而陷入危殆，这样才可以长久。","【读法】知足、知止在这里承接声名、财货与自身的轻重。所据录文此处未见独立王注，不补造原注；可以长久是章内节欲保身的判断，不是保证知足者永不受辱、遇险。","【读法】知足不取消改善生活的行动，知止也不是遇到困难便放弃；它要求辨明已经付出的代价是否损害了更切近的自身。"]}],r=[{id:"ming",term:"名",sense:3},{id:"shu",term:"孰",sense:1},{id:"huo",term:"货",sense:1},{id:"duo",term:"多",sense:1},{id:"bing",term:"病",sense:1},{id:"wang",term:"亡",sense:1,context:"得与亡问得利与丧失自身，厚亡则写重大的损失。"},{id:"shenai",term:"甚爱",sense:1},{id:"cang",term:"藏",sense:1},{id:"zhizu",term:"知足",sense:1},{id:"zhizhi",term:"知止",sense:1},{id:"dai",term:"殆",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十四章",tabindex:"-1"},[s("道德经第四十四章 "),a("a",{class:"header-anchor",href:"#道德经第四十四章","aria-label":'Permalink to "道德经第四十四章"'},"​")],-1)),o(i,{title:"声名、财货与自身，什么更值得珍重",summary:"本章先用三个孰字追问名、身、货与得失的轻重，再说过度执爱和积藏的代价，以知足知止收束。王弼特别提醒，追逐声名、贪求财货，可能使人反而疏远、轻忽自身。",points:[{label:"先读",text:"名在这里是声名，货是财货；多在孰多中问轻重，不只问数量。"},{label:"再辨",text:"甚爱指过分执爱，多藏指过度囤积，不能把所有关爱和储备都视为问题。"},{label:"后看",text:"知足知止要落到名货与自身的分际，勿读成对一切风险的保证。"}],hint:"孰读 shú，藏读 cáng，殆读 dài；亡在此兼有丧失自身、遭受损失的意思。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"名与身孰亲？身与货孰多？得与亡孰病？",tone:"重新衡量得失",guide:"取得声名或财货时，仍须问是否牺牲了自身。"},{text:"甚爱必大费，多藏必厚亡。",tone:"无度执藏的代价",guide:"辨清过度执取与正常珍惜、储备的差别。"},{text:"故知足不辱，知止不殆，可以长久。",tone:"满足与停止的分际",guide:"把知足知止放回名货与自身的比较，成为可执行的限度。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么先用三个问题而不直接劝知足" tabindex="-1">象：为什么先用三个问题而不直接劝知足？ <a class="header-anchor" href="#象-为什么先用三个问题而不直接劝知足" aria-label="Permalink to &quot;象：为什么先用三个问题而不直接劝知足？&quot;">​</a></h3><p>三个孰字让人自己比较所亲、所重和所忧。若不先辨清得名得货与自身的轻重，知足容易只剩一句空泛劝告。</p><h3 id="理-爱与藏为什么会反过来造成损失" tabindex="-1">理：爱与藏为什么会反过来造成损失？ <a class="header-anchor" href="#理-爱与藏为什么会反过来造成损失" aria-label="Permalink to &quot;理：爱与藏为什么会反过来造成损失？&quot;">​</a></h3><p>问题在甚与多：当珍惜变成不肯通达、分享和调整的执取，占有就可能牵动无尽付出与争求。王弼从求者、攻者的增多说明这种反转，而非反对全部爱惜与储备。</p><h3 id="用-今天怎样为自己设定知止的界线" tabindex="-1">用：今天怎样为自己设定知止的界线？ <a class="header-anchor" href="#用-今天怎样为自己设定知止的界线" aria-label="Permalink to &quot;用：今天怎样为自己设定知止的界线？&quot;">​</a></h3><p>可先说清某项追求服务什么，再列出不可无限交换的条件，如健康、基本生活与必要关系。代价越过这些条件时，应重新判断目标与做法，而不是只为已经投入很多继续追逐。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把代价也放进得失账。</strong> 升迁、收入和声誉都可以是正当追求，但衡量时应连时间、身体和关系一起看。多一项外在所得，未必抵得过自身长期损耗。</p><p><strong>提前约定停止的条件。</strong> 在投入尚小时明确预算、时间和退出条件，可以减少临场被欲望与沉没成本牵走。界线也须随实际处境审慎修订。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我所称的得到，是否包含了没有看见的自身损失？我能否在继续投入之前，说清楚什么程度已经足够、哪里应当停下？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留；卷三 008a–008b 录文在甚爱前作是故，知足前未见本站的故，未静默混改。</li><li>名新增声名义，多取重视、看重义；亡沿丧失义，并在本页交代亡身与厚亡的语境差别。</li><li>古注用于解释三问和执藏的代价；知足知止段未见独立注，本站读法另标，不以经句或现代转述冒充王注。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，008a–008b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
